FUNCTION_BLOCK FB_MonitorStartStop
VAR_INPUT
    Start_Stop  : BOOL;
END_VAR
VAR_OUTPUT
    ONS_Trig    : BOOL;
    Rising_ONS  : BOOL;
END_VAR
VAR
    Prev_Start_Stop : BOOL := FALSE;  // Variable to store the previous state of Start_Stop
    ON_OFF          : BOOL := FALSE;  // Internal variable to manage ON/OFF state
END_VAR

(* Detect rising edge: ONS_Trig is TRUE only when Start_Stop changes from FALSE to TRUE *)
ONS_Trig := (NOT Prev_Start_Stop) AND Start_Stop;

(* Update ON_OFF based on XOR operation between ONS_Trig and ON_OFF *)
ON_OFF := ONS_Trig XOR ON_OFF;

(* Store the current state of Start_Stop for the next cycle *)
Prev_Start_Stop := Start_Stop;

(* Update Rising_ONS to reflect the current state of Start_Stop *)
Rising_ONS := Start_Stop;

END_FUNCTION_BLOCK
